intro70 = ('《数经》为西晋沙门释法炬所译。经中记一位以算数为业的婆罗门来到舍卫城东园鹿讲堂，'
           '向佛请问：世间技艺皆有次第教授、次第修学，如建讲堂由阶梯次第而上、御象者执钩而学、'
           '乘马者习羁绊、刹帝利学弓箭、婆罗门学诗章，他与弟子以算数维生，也是次第教授、次第修学，'
           '那么佛法戒律之中，是以什么教授、学什么而能了知？佛答：佛法亦有次第——初学比丘先净身口意，'
           '次修身、受、心、法四念处，次守护六根门，次则行住坐卧、着衣持钵皆行平等，终则离五盖、住四禅。'
           '佛又以罗阅祇道路为喻，说明虽有涅槃与涅槃之道、佛亦住世教授，然受教与否、行与不行全在学人自己。'
           '婆罗门信解，以娑罗林、诸香花为喻赞叹佛法，终自归依三宝，受持优婆塞戒。')

segs70 = [
 (0, 3, '''【经题与缘起】本经由西晋沙门释法炬译出。我是这样听说的：有一次，婆伽婆（世尊）在舍卫城东园中的鹿讲堂。那时，有一位数婆罗门，在午斋之后四处漫步游行，来到世尊所在之处。到了以后，与世尊互相当面慰问。互相慰问之后，退坐一边。那位数婆罗门退坐一边之后，禀白世尊说：「这位瞿昙（佛的族姓称呼）！我想有所请问，请听我的提问。」【义解】「婆伽婆」为佛的尊号之一，意为世尊；「舍卫城」为憍萨罗国都城；「瞿昙」为佛陀的族姓（乔达摩），外道常以此称佛；「中食后」即用过午斋之后。此段为全经缘起，数婆罗门来诣佛所，请问佛法中教授、修学的次第。'''),
 (3, 5, '''【婆罗门以世间次第为问】「听你提问，婆罗门！随你心意所乐。」\n「这位瞿昙！这鹿讲堂是次第建造、次第完成的。瞿昙！这鹿讲堂起初逐级上台阶，如此一、二、三、四。瞿昙！这鹿讲堂就是这样次第登上的。瞿昙！这调御大象的人，是次第教授、次第学习的，说的是手执钩子。瞿昙！这乘马的人，是次第教授、次第学习的，说的是套上羁绊（马具）。这位瞿昙！所谓刹利种（刹帝利），是次第教授、次第学习的，说的是持弓箭。瞿昙！这婆罗门，是次第教授、次第学习的，说的是学诗章。瞿昙！我们学算数，靠算数来维持生活。至于教算数的弟子，比如说有个小儿，先教他一、二的数法，二三二三，或者十，或者百，或者更多。就是这样，瞿昙！我们学算数、靠算数维生，是次第教授、次第学习的，说的是学算数。沙门瞿昙！在这法（佛法）与律（戒律）之中，是以什么教授、学什么而能了知呢？」【义解】婆罗门以建讲堂须循梯次第而登、驯象者执钩、乘马者习羁绊、刹帝利习射、婆罗门学诗、自家学数为喻，指出一切技艺皆「次第教授、次第学」，从而问佛：佛法戒律中是否也有次第教授与修学。'''),
 (5, 6, '''【佛答：佛法亦次第教授修学】「你这个算数者目犍连！若这样说，是平等之说吗？（也就是说）次第教授、次第学，行戒、教学。目犍连！若这样说，是次第之说吗？在我法与律之中，是什么缘故，目犍连！在我法与律中次第有教授、次第行戒、次第学呢？目犍连！就是说，那比丘初学不久，来到这法与律中，也还未曾从如来受教语。这比丘！应当以身行平等清净其行，口、意平等清净其行。目犍连！若比丘身行平等清净其行，口、意平等清净其行，那就是如来无上的调御。【义解】此段佛肯定佛法确有「次第教授、次第行戒、次第学」，其入手处即「净身口意」：初学比丘未受如来教语之前，先使身行、口行、意行平等清净。经中「目犍连」为这位数婆罗门的名字，与佛弟子大目犍连同名而异人。'''),
 (6, 7, '''【修身、受、心、法四念处】「这比丘，应当于内身作身相观而行止（安住），乃至受（痛）、心（意）、法的法相观而行止。目犍连！这就是说，比丘于内身作身相观而行止，乃至受、心、法的法相观而行止，那便是如来无上的调御。」【义解】此即四念处：身念处、受念处、心念处、法念处。经中「痛」即受、「意」即心；「观行止」指以观慧安住于所观之境。四念处是此经次第修学中的第二层次。'''),
 (7, 9, '''【守护根门与一切威仪行平等】「这比丘，应当守护根门，自己守护其心、守护意念，一同自行精进；当他眼见到色时，不要领受想、不要领受他（异）想，因为这是增上（强盛）因缘之故。（应当）守护眼根，使无有可耻的贪、忧、悲戚之意，不落在恶不善法中，他就在这中间修学守护眼根；耳、鼻、舌、身、意根也是这样，身、意了知法时，不要领受想、不要领受他想，因为这是增上因缘之故。这意根无可耻的贪忧悲戚之意，不善法不留在意中，他就在这中间修学自己守护意根。目犍连！若比丘具足诸根门的守护，自己守护其心，心无染污地护意，心与念一同平等修行精进；当他眼见到色时，也不领受想、不领受他想，因为增上缘之故。具足眼根（的守护），无可耻的贪忧悲戚之意，不落在恶不善法中，他就在这中间修学自己守护眼根；耳、鼻、舌、身、意了知法时也是这样，也不领受想，乃至在那中间修学自己守护意根，那便是如来无上的调御。\n「这比丘，于已过（过去）之事应当作平等行观；已经观（之后），（无论）屈伸、持僧伽梨（大衣）与钵，或行、或住、或坐，或眠、或觉、或说话、或沉默，都应当行平等。目犍连！若比丘，对已过之事一直到（现在）都行于平等行，那便是如来无上的调御。」【义解】此段先说守护六根门：眼见色乃至意知法，皆不取相、不取随好（「莫受想、莫受他想」即不领受总相与别相），使贪忧恶法不入意中；次说一切威仪——屈伸、着衣持钵、行住坐卧、眠觉语默——皆行平等。经中「僧伽梨」为比丘三衣之一（大衣）。'''),
 (9, 10, '''【离五盖、住四禅】「这比丘，知道床卧之处而受用，或在静处，或在树下、空闲寂静处、山间窟中，或露天坐在草褥上、林间、坟冢间。他若在静处，依所敷的尼师檀（坐具）结跏趺坐，端正身体、专注意愿，把意念放在最前；除去贪嫉之意，安住于无瞋恚中；不要对他人的财物生起贪著，想着「他物使我拥有」，清净除去贪意。像这样，除去瞋恚、懈怠、睡眠、调戏（掉悔）、羞耻（恶作），除去疑与贪，远离邪、远离疑、远离种种犹豫之法，使疑意清净。他舍弃五盖之心与所著的结缚，智慧（由此）得以超越、于淫（欲）解脱，进而安住四禅。就是这样，目犍连！比丘从淫欲中解脱，进而安住四禅。就是这样，目犍连！如来为初学的比丘多有利益，就是说教授、教导、教令修行。」【义解】此段述次第修学的最后阶段：先择静处、结跏趺坐、除贪瞋，次舍五盖（贪嫉、瞋恚、睡眠、掉悔、疑等），离欲解脱，安住四禅。经中「尼师檀」为坐具；「五盖」为覆盖心性的五种烦恼。原文「智慧羸」一句文义欠明，姑从「智慧明净、离欲解脱」理解。'''),
 (10, 12, '''【上首比丘与更问因缘】「目犍连！那些比丘中的上首尊者，是诸王所识知的，住于不懈怠，修行梵行，这正是如来无上的调御。就是说，究竟穷尽、有漏已尽；一切沙门瞿昙的弟子，这样教授、这样教导学，究竟穷尽、近于涅槃。目犍连！这并不是一向如此——或者有一（人）不如此，或者一向（皆）如此。」\n「这位瞿昙！有什么因、什么缘，说（佛）有涅槃、求涅槃之道？沙门瞿昙！您住世能够教授，或者一比丘这样教授、这样教导学，究竟穷尽、究竟向涅槃；或者有一（人）不是这样。」【义解】佛先说上首比丘无懈怠、行梵行、漏尽近涅槃；然又以「非一向或一不或一向」点出：众生根机与受教奉行各有不同，故证果与否不能一概而论。婆罗门随即追问此中因缘。'''),
 (12, 15, '''【罗阅祇道路之喻】「所以，目犍连！我反过来问你，随你所乐而回答我。目犍连，你的意思如何？你善于知道通往罗阅祇的道路吗？」\n「是的，瞿昙！我善于知道通往罗阅祇的道路。」\n「如果有人来，想要到罗阅祇、到国王那里，来到你处这样说：『目犍连婆罗门善于知道通往罗阅祇的道路，我想去罗阅祇到国王那里，来问道路。』你应当这样说：『你应当循这条道端正前行，正行之后到那个村落，到了那个村落之后到那地方，因此你次第便会到达罗阅祇。至于罗阅祇，园地快乐，树林快乐、土地快乐，池沼快乐、河水流冷，安隐快乐。你应当知道这些、应当见到这些。』那人应当接受你的教导、平等受其教；受教之后，顺着那条道一直前行到那里。到了那里之后，反过来取邪道，背道而行。那么他对罗阅祇的园地快乐乃至安隐快乐，既不知道、也不看见。如果有人来，为王事想到罗阅祇，来到你处，应当这样说：『目犍连婆罗门善于知道通往罗阅祇的道路，我想去罗阅祇，我现在问你道路。』你应当这样说：『你循这条道一直前往而到，前往之后到那个村落，到了那个村落之后到那地方。他次第便会到达罗阅祇，对于那罗阅祇的园地快乐乃至安隐快乐，他知道、他看见。』目犍连！是什么因、什么缘，有那罗阅祇？有通往罗阅祇的道路？你住世教授，那首先来的人虽然得到教授，却不接受教授，反而取邪道背道而去，对于罗阅祇的园地快乐乃至安隐快乐，他既不知道、也不看见。而那（另一）人如你所教，接受其教、取其道，次第到达罗阅祇，对罗阅祇的园地快乐乃至安隐快乐，他便知道、他便看见。」【义解】此段以「罗阅祇道路」为喻：罗阅祇（王舍城）喻涅槃，道路喻涅槃之道，教授者喻佛。佛虽住世教授，然第一人虽得教授却不信受、反取邪道，故不能知见涅槃之乐；第二人依法而行，故能知见。喻示修行成否在于学人自身是否受教奉行。'''),
 (15, 16, '''【婆罗门领解】「这位瞿昙！我该怎样呢？（正如）有那罗阅祇、有通往罗阅祇的道路，我住世教授，那首先来的人，如我所教却不接受教导，取邪道反道而行，对于罗阅祇的园地快乐乃至安隐快乐，他既不知、也不见；而另一人如我教授，接受其教、取其道，次第到达罗阅祇，对于罗阅祇的园地快乐乃至安隐快乐，他应当知道、应当看见。」【义解】婆罗门以同样的喻义复述佛语，表明他已领会：道路（法）虽同，行与不行、受教与不受教，决定能否到达（涅槃）。此为一重「领解」。'''),
 (16, 17, '''【以喻合法】「就是这样，目犍连！我也是如此。（世间）有那涅槃、有涅槃之道，我住世教授，或者一比丘，这样教授、这样教令，究竟穷尽、近于涅槃；或者有一（人）不如此。目犍连！就是说，那比丘在其中接受教导，在世尊的大众中受教授、被授记，即究竟穷尽、有漏已尽。」【义解】佛以道路之喻合于佛法：涅槃与涅槃之道真实存在，佛亦如实教授，但弟子中有人依法得证究竟（漏尽）、有人则否。故前说「非一向」，正因学人受教与否不同。'''),
 (17, 18, '''【娑罗林与香花之喻，婆罗门归依】「（佛的教说）已超过（一切）了，瞿昙！已超过（一切）了，瞿昙！譬如，瞿昙！有一块极好的土地，上面有娑罗树林，那守护娑罗树林的人勤修不懈，他凭自己的力量，连同那娑罗树的根，按时穿掘查看，把粪投入其中，用水浇灌；若有欠缺就以土填满；若旁边有草就拔掉丢弃；若旁边有弊恶弯曲、委曲不直的蔓草，所当防除的都拔除丢弃。就是说，他舍弃新生的（劣苗），让那初生的（好苗）长得极长，随时浇水整治，投入粪肥，用水浇灌。就是这样，瞿昙！好地上的娑罗树林，后来便极为增长。就是这样，瞿昙！至于那种谄媚欺诈、无有诚信、懈怠、心志散乱不定、恶智意乱、诸根不定、戒行不勤、不能善加分别沙门之行的人，沙门瞿昙！我不与他同宿，不与这样的人共住。为什么呢？瞿昙！像这样的人，是破坏梵行的人。瞿昙！至于那种没有谄媚、也没有邪意、具足信心、精进行持、心意恒常安住、相应于定与智慧、随顺恭敬戒学、善于分别沙门之行的人，沙门瞿昙！我（虽）无所执著，也与这样的人同宿共住。为什么呢？瞿昙！像这样的人，对于梵行者来说是应法清净的。譬如，瞿昙！一切根香之中，迦罗（香）最为上等。为什么呢？瞿昙！那迦罗是一切根香之首。譬如，瞿昙！一切娑罗香之中，赤栴檀是其中之首，为什么呢？瞿昙！因为一切娑罗香中，赤栴檀为首。譬如，瞿昙！一切水中之华，青忧钵（青莲花）为首。为什么呢？瞿昙！因为一切水华中，青忧钵为首。譬如，瞿昙！一切陆地之华，须牟尼婆利师（茉莉花）为首。为什么呢？瞿昙！因为一切陆地华中，婆利师为首。譬如，瞿昙！一切世间的论议之中，沙门瞿昙之论最为上。为什么呢？因为沙门瞿昙之论，能统摄一切异学之故。所以，唯愿世尊！我今自归依法及比丘僧。唯愿世尊！我今受持（成为）优婆塞，从今日起尽此一生远离杀生，现在自归依。」佛陀这样说。常数的目犍连婆罗门听闻佛陀所说，欢喜而乐。【义解】此段以娑罗林须勤加守护方能增长，喻修行须断除谄曲、懈怠等恶法而长养信、精进、定慧、戒学；又以迦罗香、赤栴檀、青忧钵、婆利师（茉莉）依次为根香、木香、水生花、陆生花之首，喻佛之论议能统摄一切异学。婆罗门于是自归依佛法僧，受持优婆塞（在家居士）戒，尽形寿不杀生。经末以闻法欢喜作结。'''),
]

def build(src, blocks, intro, segs, title, translator):
    out = {
        'id': src['id'],
        'title': title,
        'translator': translator,
        'mode': '白话',
        'intro': intro,
        'translations': [],
    }
    for i, (s, e, modern) in enumerate(segs):
        preview = '\n'.join(blocks[s:e])
        if i > 0:
            preview = '\n' + preview
        out['translations'].append({
            'id': 'seg' + str(i + 1),
            'original_preview': preview,
            'modern': modern,
        })
    return out

def check(src, out):
    full = src['full_text']
    joined = ''.join(t['original_preview'] for t in out['translations'])
    ok = (joined == full)
    print(src['id'], 'segments=', len(out['translations']), 'coverage_exact=', ok, 'len_src=', len(full), 'len_join=', len(joined))
    if not ok:
        # locate first diff
        for k in range(min(len(full), len(joined))):
            if full[k] != joined[k]:
                print('first diff at', k, repr(full[k-20:k+20]), '|', repr(joined[k-20:k+20]))
                break
    # quote check
    for t in out['translations']:
        assert '"' not in t['modern'], t['id']
        assert "'" not in t['modern'], t['id']
    return ok

o67 = build(t67, b67, intro67, segs67, '弊魔试目连经', '吴 支谦译')
o70 = build(t70, b70, intro70, segs70, '数经', '西晋 法炬译')

ok1 = check(t67, o67)
ok2 = check(t70, o70)

os.makedirs(OUT_DIR, exist_ok=True)
if ok1:
    with open(os.path.join(OUT_DIR, 't0067.json'), 'w', encoding='utf-8') as f:
        json.dump(o67, f, ensure_ascii=False, indent=1)
    print('wrote t0067')
if ok2:
    with open(os.path.join(OUT_DIR, 't0070.json'), 'w', encoding='utf-8') as f:
        json.dump(o70, f, ensure_ascii=False, indent=1)
    print('wrote t0070')
